1 EntailmentStrengthScores empty   
list;   
2 foreach Step (If , Then ) in E do   
3 EntailmentScore nli(If ,   
T hen<sub>s</sub>);   
4 ContradictionScore nli(If<sub>s</sub>,   
T hen<sub>s</sub>);   
5 EntailmentStrength   
